async def assign_orders(
    session: AsyncSession,
    tenant_id: uuid.UUID,
    supply_id: uuid.UUID,
    box_id: uuid.UUID,
    order_ids: list[uuid.UUID],
    *,
    actor_user_id: uuid.UUID | None,
    order_product_ids: list[uuid.UUID] | None = None,
) -> None:
