            except MarketplaceProviderError as exc:
                _raise_ozon_provider_http(exc)
        return FbsOrderSyncOut(id="", status="done")
    payload: dict[str, Any] = {"seller_id": str(body.seller_id)}
    job = await job_svc.create_pending_job(
        session,
