"""Одна точка, где решается: провайдер Ozon боевой или локальный.

До этого модуля выбор транспорта был размазан по десяти местам, и все десять
жёстко создавали ``FakeMarketplaceTransport``. Переключить модуль на живые
вызовы конфигом было нельзя в принципе — только правкой кода в десяти файлах.

Теперь решение принимается здесь и ровно по одному признаку — настройке
``ozon_live_api_enabled``. Пока она выключена (умолчание), поведение системы
не меняется ни на шаг: те же фейки, те же ошибки, те же тесты. Как только её
включат, все десять точек уходят в кабинет одновременно, а не по одной.

Аргумент ``blocked_operation`` сохраняет прежнюю локальную семантику: в
автоопросе и в отгрузке фейк намеренно отвечает «403, код 7» на конкретной
операции, чтобы локальный путь не выглядел успешным. Это поведение остаётся
в точности прежним при выключенном флаге.
"""

from __future__ import annotations

from app.core.settings import settings
from app.services.marketplace_provider import (
    FakeMarketplaceTransport,
    MarketplaceProviderError,
    MarketplaceTransport,
    OzonMarketplaceProvider,
)
from app.services.ozon_marketplace_transport import HttpxOzonMarketplaceTransport


def ozon_live_api_enabled() -> bool:
    return bool(settings.ozon_live_api_enabled)


def build_ozon_transport(*, blocked_operation: str | None = None) -> MarketplaceTransport:
    if ozon_live_api_enabled():
        return HttpxOzonMarketplaceTransport()
    if blocked_operation is None:
        return FakeMarketplaceTransport()
    return FakeMarketplaceTransport(
        errors={blocked_operation: MarketplaceProviderError("ozon", 403, {"code": 7})}
    )


def build_ozon_provider(*, blocked_operation: str | None = None) -> OzonMarketplaceProvider:
    """Return the provider every Ozon call site should use instead of building its own."""
    return OzonMarketplaceProvider(
        transport=build_ozon_transport(blocked_operation=blocked_operation)
    )

    }


def _normalized_optional(raw: object) -> str | None:
    if not isinstance(raw, str):
        return None
    normalized = normalize_scanned_sticker(raw)
    return normalized or None


def _find_order_by_sticker(orders: list[FbsOrder], sticker: str) -> FbsOrder | None:
    # Сначала — технический код стикера. Именно он закодирован во все QR и штрихкоды
    # печатной этикетки WB, и именно его выдаёт сканер (вид «*DUIkWJJF»). Проверено
    # 20.08.2026 декодированием реальной этикетки: раньше поиск шёл только по
    # человеческому номеру partA/partB, поэтому скан не находил заказ никогда.
    for order in orders:
        if _normalized_optional(order.sticker_barcode) == sticker:
            return order
    # Человеческий номер («5694425 3074») — если оператор вводит его руками с этикетки.
    for order in orders:
        if _normalized_optional(order.sticker_code) == sticker:
            return order
    # Штрихкод товара — запасной путь, когда стикер заказа ещё не получен.
    for order in orders:
        if _normalized_optional(order.wb_barcode) == sticker:
            return order
    return None


def _find_order_by_universal_test_sticker(
    orders: list[FbsOrder], candidates: list[str]
) -> FbsOrder | None:
    configured = settings.fbs_universal_test_sticker
    if not configured:
        return None
    configured_candidates = sticker_scan_candidates(configured)
    if not set(candidates).intersection(configured_candidates):
        return None
    writable = [
        order
        for order in orders
        if order.status in FBS_ORDER_MARKING_WRITE_STATUSES
        and order.status not in FBS_ORDER_MARKING_FROZEN_STATUSES
        and _current_sgtin_marking(order) is None
    ]
    return min(writable, key=lambda order: (order.wb_order_id, order.id), default=None)


def _current_sgtin_marking(order: FbsOrder) -> FbsOrderMarking | None:
    return current_order_marking(list(order.markings), MARKING_KIND_SGTIN)


